(function () {
  const darkModeMediaQuery = window.matchMedia('(prefers-color-scheme: dark)')
  let initialTheme
  if (localStorage.getItem('darkmode-pref-set') === 'true') {
    initialTheme = localStorage.getItem('darkMode') === 'true'
  } else {
    initialTheme = darkModeMediaQuery.matches
  }

  function updateToggle (darkMode) {
    document.querySelector(".theme-toggle input[type=radio][value='dark']").checked = darkMode
    document.querySelector(".theme-toggle input[type=radio][value='light']").checked = !darkMode

    document.body.classList.toggle('dark-mode', darkMode)
    localStorage.setItem('darkMode', darkMode)
    localStorage.setItem('darkmode-pref-set', 'true')
  }

  darkModeMediaQuery.addEventListener('change', (e) => {
    const darkModeOn = e.matches
    updateToggle(darkModeOn)
  })

  window.addEventListener('load', function () {
    const radios = document.querySelectorAll('.theme-toggle input[type=radio]')
    radios.forEach((radio) => {
      radio.addEventListener('change', function (e) {
        updateToggle(e.target.value === 'dark')
      })
    })

    updateToggle(initialTheme)
  })
})()

.sect2 {
    border-radius: 25px;
    border: 2px solid var(--bs-body-color);
    padding: 20px;
    margin: 20px 0px 20px 0px;
}

.progress {
    margin: 20px 0px 20px 0px;
}

.dropdown-menu {
    max-height: 540px;
    overflow-y: auto;
}

@media only screen and (max-width: 990px) {
    .dropdown-menu {
        max-height: 320px;
        overflow-y: auto;
    }
}

@media only screen and (max-width: 990px) and (max-height: 600px) {
    .dropdown-menu {
        max-height: 200px;
        overflow-y: auto;
    }
}

.thank-you {
    border-radius: 25px;
    border: 2px solid var(--bs-body-color) !important;
    padding: 10px 16px;
    margin: 0px 0px 10px 0px;
}

@media only screen and (max-width: 990px){
    .thank-you {
        border-radius: 25px;
        border: 2px solid var(--bs-body-color) !important;
        padding: 10px;
        margin: 0px 0px 10px 0px;
    }
}

a.disabled {
    cursor: default;
    pointer-events: none;
    text-decoration: none;
    color: var(--bs-body-color);
}
.theme-toggle input[type="radio"] {
    position: absolute;
    opacity: 0;
    cursor: pointer;
    height: 0;
    width: 0;
}

.theme-toggle :checked + .checkmark {
    border-bottom: 1px solid var(--bs-gray-300);
}

tr.solved {
    --bs-success-soft: rgba(0, 188, 140, 0.5);
    background-color: var(--bs-success-soft) !important;
}

.table {
    --bs-table-bg: rgba(0, 0, 0, 0) !important;
}

.dark-mode {
    --bs-blue: #375a7f;
    --bs-indigo: #673ab7;
    --bs-light-purple: #9c7dd2;
    --bs-purple: #9c7dd2;
    --bs-pink: #e83e8c;
    --bs-red: #e74c3c;
    --bs-orange: #fd7e14;
    --bs-yellow: #f39c12;
    --bs-green: #00bc8c;
    --bs-teal: #45b5aa;
    --bs-cyan: #17a2b8;
    --bs-white: #fafafa;
    --bs-black: #111;
    --bs-gray: #7e7e7e;
    --bs-gray-dark: #121212;
    --bs-gray-100: #e1e1e1;
    --bs-gray-200: #cfcfcf;
    --bs-gray-300: #b1b1b1;
    --bs-gray-400: #9e9e9e;
    --bs-gray-500: #7e7e7e;
    --bs-gray-600: #626262;
    --bs-gray-700: #515151;
    --bs-gray-800: #3b3b3b;
    --bs-gray-900: #222;
    --bs-primary: #375a7f;
    --bs-secondary: #626262;
    --bs-success: #00bc8c;
    --bs-info: #17a2b8;
    --bs-warning: #f39c12;
    --bs-danger: #e74c3c;
    --bs-light: #9e9e9e;
    --bs-dark: #3b3b3b;
    --bs-primary-rgb: 55, 90, 127;
    --bs-secondary-rgb: 98, 98, 98;
    --bs-success-rgb: 0, 188, 140;
    --bs-info-rgb: 23, 162, 184;
    --bs-warning-rgb: 243, 156, 18;
    --bs-danger-rgb: 231, 76, 60;
    --bs-light-rgb: 120, 120, 120;
    --bs-dark-rgb: 59, 59, 59;
    --bs-white-rgb: 250, 250, 250;
    --bs-black-rgb: 17, 17, 17;
    --bs-body-color-rgb: 225, 225, 225;
    --bs-body-bg-rgb: 34, 34, 34;
    --bs-font-sans-serif: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans",
        "Liberation Sans", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --bs-font-monospace: SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    --bs-gradient: linear-gradient(180deg, rgba(17, 17, 17, 0.15), rgba(17, 17, 17, 0));
    --bs-body-font-family: var(--bs-font-sans-serif);
    --bs-body-font-size: 1rem;
    --bs-body-font-weight: 400;
    --bs-body-line-height: 1.5;
    --bs-body-color: #e1e1e1;
    --bs-body-bg: #222;
}

.dark-mode a {
    color: var(--bs-light-purple);
}

.dark-mode a.disabled {
    color: var(--bs-body-color);
}
.dark-mode a.btn-secondary {
    color: var(--bs-body-color);
}

.dark-mode .table {
    color: var(--bs-body-color);
    --bs-table-color: var(--bs-body-color);
}

.dark-mode .card {
    background-color: var(--bs-gray-800);
}

.dark-mode .btn-primary {
    background-color: var(--bs-primary);
    border-color: var(--bs-primary);
}
.dark-mode .btn-primary:hover {
    background-color: var(--bs-indigo);
    border-color: var(--bs-indigo);
}

.dark-mode .paginate_button {
    background-color: var(--bs-primary);
    border-color: var(--bs-primary);
    color: #7e7e7e;
}
.dark-mode .paginate_button:hover {
    background-color: var(--bs-indigo);
    border-color: var(--bs-indigo);
}

.dark-mode input {
    background-color: var(--bs-gray-600);
    color: var(--bs-body-color);
}

.dark-mode select {
    background-color: var(--bs-gray-600);
    color: var(--bs-body-color);
}

